<div class="d-flex gap-2 align-items-center mb-3"><h2 class="h4 mb-0"><?= e($a['title']) ?></h2><a class="btn btn-outline-secondary ms-auto" href="<?= url('learn/quizzes/' . (int)$a['quiz_id']) ?>">رجوع</a></div>
<div class="card-s text-center mb-3"><div class="display-5 fw-bold <?= $a['status'] === 'graded' ? 'text-success' : 'text-warning' ?>"><?= (float)$a['score'] ?> <small class="fs-5 text-muted">/ <?= (float)$a['max'] ?></small></div><div class="text-muted"><?= $a['status'] === 'graded' ? 'مُصحَّح بالكامل' : 'بانتظار تصحيح ' . (int)$a['pending'] . ' سؤال مقالي — قد تتغير الدرجة' ?></div></div>
<?php if (!$a['reveal']): ?><div class="alert alert-secondary"><?= $a['show_answers'] === 'never' ? 'لا تُعرض الإجابات الصحيحة لهذا الاختبار.' : 'تظهر الإجابات الصحيحة بعد إغلاق الاختبار.' ?></div><?php endif; ?>
<?php foreach ($a['rows'] as $i => $q): $g = $q['given']; $ok = $q['score'] !== null && (float)$q['score'] >= (float)$q['pts']; ?><div class="card-s mb-2 border-<?= $q['score'] === null ? 'warning' : ($ok ? 'success' : 'danger') ?>"><div class="d-flex gap-2"><strong><?= $i + 1 ?>.</strong><div class="flex-grow-1"><span class="math-content"><?= e($q['body']) ?></span><?= !empty($q['image_file_id']) ? '<div class="mt-2">' . qimg((int)$q['image_file_id']) . '</div>' : '' ?></div><span class="badge text-bg-<?= $q['score'] === null ? 'warning' : ($ok ? 'success' : 'danger') ?>"><?= $q['score'] === null ? 'قيد التصحيح' : (float)$q['score'] . ' / ' . (float)$q['pts'] ?></span></div>
  <div class="small mt-1">إجابتك: <strong><?= ($g === null || $g === '') ? '— لم تجب' : ($q['kind'] === 'mcq' ? qopt($q, $g) : ($q['kind'] === 'true_false' ? ($g ? 'صح' : 'خطأ') : e($g))) ?></strong></div>
  <?php if ($q['kind'] === 'mcq'): ?><div class="small text-success">الصحيح: <?= qopt($q, $q['answer']) ?></div><?php elseif ($q['kind'] === 'true_false'): ?><div class="small text-success">الصحيح: <?= $q['answer'] ? 'صح' : 'خطأ' ?></div><?php elseif ($q['kind'] === 'short' && $q['answer']): ?><div class="small text-success">المقبول: <?= e(implode(' / ', $q['answer'])) ?></div><?php endif; ?></div><?php endforeach; ?>
